create table if not exists compliance_documents(id uuid primary key default gen_random_uuid(),org_id text not null references organizations(id),document_code text not null,document_type text not null,title text not null,entity_type text not null check(entity_type in ('CLIENT','DOSSIER','PACKAGE','SHIPMENT','DEPARTURE','ORGANIZATION')),entity_id uuid,object_path text not null,file_name text not null,mime_type text not null,size_bytes bigint not null,checksum_sha256 text not null,version_number integer not null default 1,status text not null default 'PENDING_REVIEW' check(status in ('PENDING_REVIEW','VALID','REJECTED','EXPIRED','SUPERSEDED','ARCHIVED')),issued_at date,expires_at date,issuer text,rejection_reason text,metadata jsonb not null default '{}',uploaded_by text,reviewed_by text,reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,document_code,version_number));
create table if not exists compliance_requirements(id uuid primary key default gen_random_uuid(),org_id text not null references organizations(id),requirement_code text not null,document_type text not null,shipping_service_id uuid references shipping_services(id),origin_country text,destination_country text,goods_category text,entity_type text not null default 'SHIPMENT',mandatory boolean not null default true,validity_days integer,active boolean not null default true,priority integer not null default 100,unique(org_id,requirement_code));
create table if not exists compliance_checks(id uuid primary key default gen_random_uuid(),org_id text not null references organizations(id),entity_type text not null,entity_id uuid not null,status text not null check(status in ('CLEAR','BLOCKED','REVIEW_REQUIRED')),missing_requirements jsonb not null default '[]',checked_at timestamptz not null default now(),checked_by text,unique(org_id,entity_type,entity_id));
create table if not exists compliance_events(id bigserial primary key,org_id text not null references organizations(id),document_id uuid,entity_type text,entity_id uuid,event_type text not null,actor_id text,actor_name text,payload jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists idx_compliance_documents_entity on compliance_documents(org_id,entity_type,entity_id,status);create index if not exists idx_compliance_expiry on compliance_documents(org_id,expires_at,status);
insert into permissions(permission_code,description) values ('documents.read','Consulter les documents'),('documents.upload','Téléverser des documents'),('documents.review','Valider ou rejeter'),('documents.manage','Configurer la conformité'),('documents.export','Exporter le registre') on conflict(permission_code) do update set description=excluded.description;
insert into role_permissions(role_id,permission_id) select r.id,p.id from organization_roles r cross join permissions p where (r.role_code in ('OWNER','MANAGER') and p.permission_code like 'documents.%') or (r.role_code in ('OPERATOR','WAREHOUSE','FINANCE','SUPPORT') and p.permission_code in ('documents.read','documents.upload')) on conflict do nothing;
